let format='Au cabinet',slot='';
const day=document.querySelector('#day'),confirmButton=document.querySelector('#confirm'),summary=document.querySelector('#summary');
const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const localDate=[tomorrow.getFullYear(),String(tomorrow.getMonth()+1).padStart(2,'0'),String(tomorrow.getDate()).padStart(2,'0')].join('-');day.min=localDate;day.value=localDate;
function resetSummary(){confirmButton.disabled=!(slot&&day.value&&day.validity.valid);summary.textContent=slot?'Créneau sélectionné : '+slot+'. Consultez le récapitulatif.':'Sélectionnez un horaire pour continuer.';}
document.querySelectorAll('[data-format]').forEach(button=>button.addEventListener('click',()=>{format=button.dataset.format;document.querySelectorAll('[data-format]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});resetSummary();}));
document.querySelectorAll('.slots button').forEach(button=>button.addEventListener('click',()=>{slot=button.textContent;document.querySelectorAll('.slots button').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});resetSummary();}));
day.addEventListener('change',resetSummary);confirmButton.addEventListener('click',()=>{if(!day.reportValidity()||!slot)return;const date=new Date(day.value+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});summary.textContent='Simulation : '+format+', '+date+' à '+slot+'. Aucun rendez-vous n’a été enregistré.';});
const modal=document.querySelector('#legal-modal');document.querySelector('#legal').addEventListener('click',()=>modal.showModal());document.querySelector('#close-legal').addEventListener('click',()=>modal.close());
